public class HomeRun{

  private int distance;

  public HomeRun(int d){
    distance = d;
  }

  public boolean isLonger(HomeRun other){
    return distance > other.distance;
  }

  public boolean same(HomeRun other){
    return !isLonger(other) &&
      !other.isLonger(<*1>);
  }
}

HomeRun h1 = new HomeRun(500);
HomeRun h2 = new HomeRun(50 * 10);
System.out.print( h1.same(h2) );

